def update_tr_reports():
    report_files = sorted(DOCS_TR.glob("[0-9][0-9]-*-v6.1.1.md"))
    report_files = [f for f in report_files if not f.name.startswith("05-")]
    updated = 0
    for rf in report_files:
        text = rf.read_text(encoding="utf-8")
        cid_m = re.search(r'case_id:\s*"?([^"\n]+)"?', text)
        if not cid_m:
            continue
        cid = cid_m.group(1).strip()
        new_block = TR_ADIM07_BLOCKS.get(cid)
        if not new_block:
            continue

        pattern = r"###\s+ADIM 07[^\n]*\n.*?(?=\n---?\s*\n+(?:##\s+FAZ[^\n]*\n+)?###\s+ADIM 08|\n###\s+ADIM 08)"
        if not re.search(pattern, text, flags=re.DOTALL):
            print(f"WARNING: Could not match ADIM 07 pattern in {rf.name}")
            continue

        new_text = re.sub(pattern, new_block, text, count=1, flags=re.DOTALL)
        rf.write_text(new_text, encoding="utf-8")

        sha = hashlib.sha256(rf.read_bytes()).hexdigest()
        sha_path = rf.with_suffix(rf.suffix + ".sha256")
        sha_path.write_text(f"{sha}  {rf.name}\n", encoding="utf-8")
        words = len(new_block.split())
        print(f"[TR UPDATED] {cid} ({rf.name}): ADIM 07 = {words} words | SHA256={sha[:16]}...")
        updated += 1
    print(f"Total TR reports updated: {updated}/15")


def verify_all():
    import io, contextlib, sys
    from gem_lint import GemLinterV6, BLOCK, WARN

    for lang, folder in [("TR", DOCS_TR), ("EN", ROOT / "docs" / "en")]:
        files = sorted([f for f in folder.glob("[0-9][0-9]-*-v6.1.1.md") if not f.name.startswith("05-")])
        total_blocks = 0
        for f in files:
            l = GemLinterV6(str(f))
            with contextlib.redirect_stdout(io.StringIO()):
                l.run_all()
            blocks = [r for r in l.findings if r["level"] == BLOCK]
            warns = [r for r in l.findings if r["level"] == WARN]
            total_blocks += len(blocks)
            text = f.read_text(encoding="utf-8")
            cid = re.search(r'case_id:\s*"?([^"\n]+)"?', text).group(1).strip()
            if lang == "TR":
                m7 = re.search(r"(###\s+ADIM\s+0?7\b[\s\S]*?)(?=\n---?\s*\n+(?:##\s+FAZ[^\n]*\n+)?###\s+ADIM\s+0?8\b|\n###\s+ADIM\s+0?8\b)", text)
            else:
                m7 = re.search(r"(###\s+Step\s+0?7\b[\s\S]*?)(?=\n###\s+Step\s+0?8\b)", text)
            w7 = len(m7.group(1).split()) if m7 else 0
            r1 = len(re.findall(r"→", m7.group(1))) if m7 else 0
            print(f"{lang} | {cid} | {f.name:<34} | Step7 Words: {w7:3d} | Arrows(→): {r1:2d} | BLOCK: {len(blocks)} | WARN: {len(warns)}")
            for b in blocks:
                print("   BLOCK:", b)
        print(f"=== {lang} SUMMARY: {len(files)}/15 REPORTS | TOTAL BLOCKS = {total_blocks} ===\n")


if __name__ == "__main__":
    import sys
    if "--verify" in sys.argv:
        verify_all()
    else:
        update_tr_reports()

